import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_gemv_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// One block per output row m. Threads cooperatively reduce over K using
// vectorized (float4) loads plus warp/block reduction.
__global__ void gemv_kernel(const float* __restrict__ A,
                             const float* __restrict__ B,
                             float* __restrict__ C,
                             int M, int K)
{
  int m = blockIdx.x;
  if (m >= M) return;

  // Full tensors via CuTe
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(K), make_stride(Int<1>{}));

  // Row m of A: shape (K), stride 1 (contiguous)
  Tensor gA = mA(m, _);

  float sum = 0.0f;

  // Vectorized part: recast contiguous chunks to float4
  int K4 = K / 4;
  if (K4 > 0) {
    Tensor gA_head = gA(make_coord(_)).compose(make_layout(make_shape(K4 * 4)));
    Tensor gA4 = recast<float4>(gA_head);
    Tensor gB_head = mB.compose(make_layout(make_shape(K4 * 4)));
    Tensor gB4 = recast<float4>(gB_head);

    for (int i = threadIdx.x; i < K4; i += blockDim.x) {
      float4 a4 = gA4(i);
      float4 b4 = gB4(i);
      sum += a4.x * b4.x + a4.y * b4.y + a4.z * b4.z + a4.w * b4.w;
    }
  }

  // Remainder (K not divisible by 4)
  int rem_start = K4 * 4;
  for (int i = rem_start + threadIdx.x; i < K; i += blockDim.x) {
    sum += gA(i) * mB(i);
  }

  // Warp-level reduction
  unsigned mask = 0xffffffffu;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum += __shfl_down_sync(mask, sum, offset);
  }

  // Block-level reduction across warps
  __shared__ float sdata[32];
  int lane = threadIdx.x & 31;
  int wid  = threadIdx.x >> 5;

  if (lane == 0) {
    sdata[wid] = sum;
  }
  __syncthreads();

  int num_warps = (blockDim.x + 31) / 32;
  if (wid == 0) {
    float total = (lane < num_warps) ? sdata[lane] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      total += __shfl_down_sync(mask, total, offset);
    }
    if (lane == 0) {
      C[m] = total;
    }
  }
}

torch::Tensor cute_gemv_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be 2D (K, 1)");
  TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match (A.size(1) == B.size(0))");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  int M = (int)A_c.size(0);
  int K = (int)A_c.size(1);

  auto C = torch::empty({M, 1}, A.options());

  const float* ptrA = A_c.data_ptr<float>();
  const float* ptrB = B_c.data_ptr<float>();
  float* ptrC = C.data_ptr<float>();

  dim3 block(256);
  dim3 grid((unsigned)M);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemv_kernel<<<grid, block, 0, stream>>>(ptrA, ptrB, ptrC, M, K);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gemv_kernel launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_gemv = load_inline(
    name="cute_gemv_inline",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_gemv_forward"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"
    ],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom
    CuTe-based CUDA kernel: one block per output row, vectorized float4
    loads over K, and warp/block level tree reduction.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_gemv

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_gemv_forward(A, B)

